@namespace sv_9d4d54ee57c2484583c6333f2badddd6.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => OnStepClick(stepIndex)" role="button" tabindex="0">
                <span class="step-marker">
                    @if (status == "completed")
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
            @if (stepIndex < StepNames.Count - 1)
            {
                <li class="step-connector @(stepIndex < CurrentStep ? "completed" : "")" aria-hidden="true"></li>
            }
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private string GetStepStatus(int index)
    {
        if (index == CurrentStep) return "active";
        if (CompletedSteps.Contains(index)) return "completed";
        return "future";
    }

    private async Task OnStepClick(int index)
    {
        if (CompletedSteps.Contains(index))
        {
            await OnStepSelected.InvokeAsync(index);
        }
    }
}

@namespace sv_9d4d54ee57c2484583c6333f2badddd6.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" class="form-control" value="@Company"
                   @onchange="e => UpdateField(nameof(Company), e.Value?.ToString())" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" class="form-control" value="@Title"
                   @onchange="e => UpdateField(nameof(Title), e.Value?.ToString())" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@StartDate?.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateDate(true, e.Value?.ToString())" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@EndDate?.ToString("yyyy-MM-dd")"
                   disabled="@IsCurrent"
                   @onchange="e => UpdateDate(false, e.Value?.ToString())" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Description"
                  @onchange="e => UpdateField(nameof(Description), e.Value?.ToString())"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime? StartDate { get; set; }
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryUpdate> OnEntryChanged { get; set; }

    private void UpdateField(string field, string? value)
    {
        OnEntryChanged.InvokeAsync(new WorkEntryUpdate(Index, field, value));
    }

    private void UpdateDate(bool isStart, string? value)
    {
        var date = string.IsNullOrEmpty(value) ? (DateTime?)null : DateTime.Parse(value);
        var field = isStart ? "StartDate" : "EndDate";
        OnEntryChanged.InvokeAsync(new WorkEntryUpdate(Index, field, date));
    }

    private void ToggleCurrent(bool current)
    {
        OnEntryChanged.InvokeAsync(new WorkEntryUpdate(Index, "IsCurrent", current));
    }

    public record WorkEntryUpdate(int Index, string Field, object? Value);
}

@namespace sv_9d4d54ee57c2484583c6333f2badddd6.Components.Pages.Apply

<div class="reference-form">
    <div class="entry-header">
        <h4>Reference @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" class="form-control" value="@Name"
                   @onchange="e => UpdateField(nameof(Name), e.Value?.ToString())" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" class="form-control" value="@Relationship"
                   @onchange="e => UpdateField(nameof(Relationship), e.Value?.ToString())" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" class="form-control" value="@Email"
                   @onchange="e => UpdateField(nameof(Email), e.Value?.ToString())" />
        </div>
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" class="form-control" value="@Phone"
                   @onchange="e => UpdateField(nameof(Phone), e.Value?.ToString())" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = "";
    [Parameter] public string Relationship { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceUpdate> OnReferenceChanged { get; set; }

    private void UpdateField(string field, string? value)
    {
        OnReferenceChanged.InvokeAsync(new ReferenceUpdate(Index, field, value ?? ""));
    }

    public record ReferenceUpdate(int Index, string Field, string Value);
}

