        <input type="email" class="form-control" value="@Email"
               @onchange="e => Email = e.Value?.ToString() ?? string.Empty" />
        @if (emailValidating)
        {
            <span class="validation-info">Validating email...</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" class="form-control" value="@Phone"
               @onchange="e => Phone = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea class="form-control" rows="2" value="@Address"
                  @onchange="e => Address = e.Value?.ToString() ?? string.Empty"></textarea>
