@using static WorkEntryForm

<div class="step-content">
    <h3>Work History</h3>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="alert alert-danger">@errorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var entry = Entries[i];
        <WorkEntryForm Index="i"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       IsCurrent="@entry.IsCurrent"
                       Description="@entry.Description"
                       ShowRemove="@(Entries.Count > 1)"
                       OnRemove="() => RemoveEntry(entry)"
                       OnEntryChanged="HandleEntryChanged" />
    }

    <button type="button" class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-actions">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? errorMessage;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(WorkEntryModel entry)
    {
        if (Entries.Count > 1)
        {
            Entries.Remove(entry);
        }
    }

    private void HandleEntryChanged(WorkEntryUpdate update)
    {
        var entry = Entries[update.Index];
        switch (update.Field)
        {
            case "Company": entry.Company = update.Value?.ToString() ?? ""; break;
            case "Title": entry.Title = update.Value?.ToString() ?? ""; break;
            case "StartDate": entry.StartDate = update.Value as DateTime?; break;
            case "EndDate": entry.EndDate = update.Value as DateTime?; break;
            case "IsCurrent":
                entry.IsCurrent = (bool)(update.Value ?? false);
                if (entry.IsCurrent) entry.EndDate = null;
                break;
            case "Description": entry.Description = update.Value?.ToString() ?? ""; break;
        }
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == null)
            {
                errorMessage = "Each position requires at least a company name, job title, and start date.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}
