@namespace sv_9d4d54ee57c2484583c6333f2badddd6.Components.Pages.Apply
@using sv_9d4d54ee57c2484583c6333f2badddd6.Services

@inject IApplicationService ApplicationService

<div class="step-content">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="alert alert-danger">@errorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" class="form-control" value="@FullName"
               @onchange="e => FullName = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" class="form-control" value="@Email"
               @onchange="e => Email = e.Value?.ToString() ?? string.Empty" />
        @if (emailValidating)
        {
            <span class="validation-info">Validating email...</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" class="form-control" value="@Phone"
               @onchange="e => Phone = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea class="form-control" rows="2" value="@Address"
                  @onchange="e => Address = e.Value?.ToString() ?? string.Empty"></textarea>
    </div>

    <div class="step-actions">
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@emailValidating">Next</button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfoResult> OnNext { get; set; }

    private string? errorMessage;
    private bool emailValidating;

    private async Task HandleNext()
    {
        errorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            errorMessage = "All fields are required.";
            return;
        }

        emailValidating = true;
        StateHasChanged();

        var isValid = await ApplicationService.ValidateEmailAsync(Email);
        emailValidating = false;

        if (!isValid)
        {
            errorMessage = "Please enter a valid email address.";
            return;
        }

        await OnNext.InvokeAsync(new PersonalInfoResult(FullName, Email, Phone, Address));
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}

